def causal_mask(b, h, q_idx, kv_idx):
    return q_idx >= kv_idx


def score_mod(score, custom_fwd_inputs, b, h, q_idx, kv_idx):
    softmax_bias = custom_fwd_inputs.input_tensors["softmax_bias"]
    score = score + softmax_bias
    score = ((score*0.5).tanh() + 1) * 0.5
    return score

